module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);
    localparam DIV_BY_HALF = MUL2_DIV_CLK / 2;
    reg [3:0] cnt;
    reg clk_ave_r;
    reg clk_adjust_r;
    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 0;
        end
        else begin
            if(cnt == MUL2_DIV_CLK - 1) begin
                cnt <= 0;
            end
            else begin
                cnt <= cnt + 1;
            end
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            clk_ave_r <= 0;
        end
        else begin
            if((cnt == 0 || cnt == 4)) begin
                clk_ave_r <= 1;
            end
            else begin
                clk_ave_r <= 0;
            end
        end
    end

    always@(negedge clk or negedge rst_n) begin
        if(!rst_n) begin
            clk_adjust_r <= 0;
        end
        else begin
            if((cnt == 1 || cnt == 4)) begin
                clk_adjust_r <= 1;
            end
            else begin
                clk_adjust_r <= 0;
            end
        end
    end

    assign clk_div = clk_adjust_r | clk_ave_r;

endmodule
